    private static Holder<SoundEvent> createSoundEvent(final String soundName) {
        return SOUND_REGISTRY.register(soundName, () -> SoundEvent.createVariableRangeEvent(GeneralMethods.getMCResourceLocation(MOD_ID, soundName)));
    }

    public static void register(IEventBus eventBus) {
        SOUND_REGISTRY.register(eventBus);
    }
